  Fixpoint shdrslx (l : list (block * jv)) (nx : list Z) (bs : list byte) {struct l} : Prop :=
    match l, nx with
    | [], [] => bs = []
    | (b, v) :: r, x :: nr => exists hb rest, bs = hb ++ slot_tailx b x ++ rest /\ length hb = 24%nat /\ vhdr v hb /\ 0 <= x < 2^32 /\ shdrslx r nr rest
    | _, _ => False
    end.
