  Lemma slots_ok_of_chunk : forall m T (l : list (block * jv)) nx sbs,
    rw_cells asegs m (T + 16) [CB (40 * length l)%nat sbs] -> shdrslx l nx sbs -> NXOK nx ->
    Forall (fun bv : block * jv => kdeep m (fst bv) /\ vdeep m (snd bv)) l ->
    Forall (fun bv : block * jv => let '(p, K, ksz) := fst bv in shvis m K (K + ksz)) l ->
    slots_ok m T (length l).
Proof.
